//! The ssh config roster writes to `~/.ssh/config.d/roster`, in the same
//! format as the Python roster's, so `ssh HOST` works by name.

use crate::inventory::Inventory;
use std::fmt::Write;
use std::path::Path;

/// One block per Host, sorted by name, under a two-line header.
pub fn render(inv: &Inventory, from: &Path) -> String {
    let mut out = format!(
        "# Generated by roster from {}\n\
         # Written whole by `roster sync`: edit roster.yml, not this file.\n",
        from.display()
    );
    let mut hosts: Vec<_> = inv.hosts.iter().collect();
    hosts.sort_by(|a, b| a.name.cmp(&b.name));
    for h in hosts {
        let title = if h.title.is_empty() {
            &h.name
        } else {
            &h.title
        };
        let _ = write!(
            out,
            "\n# {title} [{}]\nHost {}\n    HostName {}\n    User {}\n    Port {}\n\
             \x20   UserKnownHostsFile \"~/.ssh/roster_known_hosts\"\n\
             \x20   StrictHostKeyChecking accept-new\n\
             \x20   ConnectTimeout 10\n\
             \x20   ServerAliveInterval 30\n",
            h.group,
            h.name,
            h.ip.replace('%', "%%"),
            h.user,
            h.port
        );
        out += if h.os == "windows" {
            "    ControlMaster no\n"
        } else {
            "    ControlMaster auto\n    ControlPath \"~/.ssh/cm-%C\"\n    ControlPersist 10m\n"
        };
        if h.enroll {
            let _ = writeln!(out, "    IdentityFile \"{}\"", inv.key_of(h));
            out += "    IdentitiesOnly yes\n";
        } else {
            out += "    IdentitiesOnly yes\n    PubkeyAuthentication no\n";
        }
    }
    out
}

/// `~/.ssh/config` with `Include "<path>"` on top, or None when an Include
/// of `.ssh/config.d/roster` (absolute or `~/`) is already there.
pub fn with_include(config: &str, path: &Path) -> Option<String> {
    let line = include_line(path);
    let included = config.lines().any(|l| {
        let mut words = l.split_whitespace();
        words
            .next()
            .is_some_and(|w| w.eq_ignore_ascii_case("include"))
            && words.any(|w| w.trim_matches('"').ends_with(".ssh/config.d/roster"))
    });
    (!included).then(|| format!("{line}\n{config}"))
}

/// The line `Include "<path>"` that `with_include` adds.
pub fn include_line(path: &Path) -> String {
    format!("Include \"{}\"", path.display())
}

/// `text` without the lines that are exactly `line`; None when there's none.
pub fn without_line(text: &str, line: &str) -> Option<String> {
    let kept: Vec<&str> = text.lines().filter(|l| *l != line).collect();
    if kept.len() == text.lines().count() {
        return None;
    }
    let ends = text.ends_with('\n') && !kept.is_empty();
    Some(kept.join("\n") + if ends { "\n" } else { "" })
}
